import { Suspense } from "react";
import { IonPage, IonContent } from "@ionic/react";

import PageViewer from "./PageViewer";

export function Main() {
  return (
    <IonPage>
      <IonContent fullscreen={true}>
        <Suspense fallback={null}>
          <PageViewer />
        </Suspense>
      </IonContent>
    </IonPage>
  );
}
